INSERT INTO feature VALUES('syntax-ledger','workflow','The syntax ledger',NULL,'implemented','notable',NULL,'The language surface enumerated from the grammar itself — every rule and attribute, pinned by the grammar fingerprint, regenerated and compared by a gate; one verified exemplar per rule, the bijection and the mold check gated, every exemplar stating what the checker makes of its form, and every committed rule''s admission read off its exemplar''s lowering. Each old spelling that the grammar still parses is a row with the spelling that replaces it and the open issue that removes it.','surface-grammar workflow-ledger-tasks','ledger/syntax.md corpus/ledger/syntax',NULL,NULL);
